import{_ as p,a0 as i,w as o,s,ao as l,I as a,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips – Create Virtual Network Cards In Ubuntu Linux","title":"Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips – Create Virtual Network Cards In Ubuntu Linux.md","filePath":"[post].md"}'),b={name:"201311/Daily Ubuntu Tips – Create Virtual Network Cards In Ubuntu Linux.md"};function d(w,t,T,m,C,U){const u=i("Link");return o(),s("div",null,[t[11]||(t[11]=l(`<h1 id="ubuntu每日小贴士-在ubuntu下创建虚拟网卡" tabindex="-1">Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡 <a class="header-anchor" href="#ubuntu每日小贴士-在ubuntu下创建虚拟网卡" aria-label="Permalink to “Ubuntu每日小贴士 - 在Ubuntu下创建虚拟网卡”">​</a></h1><p>这个教程是为那些想用Ubuntu做点小实验的用户准备的。这并不适用于所有人，尤其是那些在（正式环境中）使用生产机器的用户。</p><p>如果你对网络运行和IP网络有所了解，你应该知道在大多数情况下，每个网卡只会分配一个IP地址。我们习惯认为这是一对一的事物。</p><p>一个网卡对应一个IP地址，你在一台机器上的一个网卡及其IP地址只能绑定或运行单一的网络服务/端口。例如，如果你想在80端口运行一个web服务器，而一个IP地址和端口号只能由一个web服务器监听。这是这样设计的。</p><p>所以，网卡和IP地址并不是一对一的关系，你可以创建可以单独分配IP地址的虚拟网卡。因此，单一的物理网卡可以群集无限的子网卡或虚拟网卡。每一个都能分配它自己IP地址到对应的端口。</p><p>这个简短的教程将展示给你如何在Ubuntu上做到这些。这是在一台电脑上用一张物理网卡和单一的端口号运行及测试多个网络服务的好方式。</p><p>动手吧，运行下列命令打开网络接口文件。</p><pre><code>sudo gedit /etc/network/interfaces
</code></pre><p>然后按照下图中的步骤，添加你想要的任意多的虚拟网卡。默认情况下，Linux会给第一张网卡分配eth0的名称，所以如果你的机子只有一张网卡，那么它会被命名为eth0。</p><p>添加虚拟网卡，创建多个静态网卡并命名为eth0:1、eth0:2、eth0:3等等(eth0后面紧跟冒号和数字)。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/virtualnetworkcardubuntu.png" alt=""></p><p>对于你创建的每一个网卡，也要确保网络都是不同的子网，这是网络常识（译注：事实上并非如此，虚拟网卡完全可以是相同子网的IP地址，只要你需要）</p><p>完成以后，保存文件并用下列命令重启网络服务。</p><pre><code>sudo service networking restart
</code></pre><p>就是这样!</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/virtualnetworkcardubuntu1.png" alt=""></p><p>玩得开心!</p><hr>`,18)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(u,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-create-virtual-network-cards-in-ubuntu-linux/"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-create-virtual-network-cards-in-ubuntu-linux/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),n(u,{href:"https://github.com/Luoxcat"},{default:r(()=>[...t[2]||(t[2]=[e("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(u,{href:"https://github.com/wxy"},{default:r(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(u,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(u,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const g=p(b,[["render",d]]);export{k as __pageData,g as default};
